# unique_pairs :: [1, 2, 3, 4]
def unique_pairs(xs):
    s = list(set(xs))
    out = []
    for i in range(len(s)):
        for j in range(i + 1, len(s)):
            out.append((s[i], s[j]))
    return out

if __name__ == '__main__':
    print(unique_pairs([1, 2, 3, 4]))

